import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

import { describe, expect, it } from '@jest/globals';

// @generated by scripts/gen-registry.mjs (region: config-imports) - do not edit; run bun run regen
import { NitroUiButtonConfig } from '../components/Button/NitroUiButtonConfig';
import { NitroUiDatePickerConfig } from '../components/DatePicker/NitroUiDatePickerConfig';
import { NitroUiPickerConfig } from '../components/Picker/NitroUiPickerConfig';
import { NitroUiProgressConfig } from '../components/Progress/NitroUiProgressConfig';
import { NitroUiSegmentedControlConfig } from '../components/SegmentedControl/NitroUiSegmentedControlConfig';
import { NitroUiSliderConfig } from '../components/Slider/NitroUiSliderConfig';
import { NitroUiSwitchConfig } from '../components/Switch/NitroUiSwitchConfig';
import { NitroUiMenuConfig } from '../components/Menu/NitroUiMenuConfig';
// @end-generated
// `<Host>` is a container rather than a control, so it has no manifest and the
// registry writes no row for it. The "covers every generated config" test below is
// what fails if a Hybrid View arrives without a manifest, or without its row here.
import { NitroUiHostConfig } from '../components/Host/NitroUiHostConfig';

const generatedDir = join(
  __dirname,
  '..',
  '..',
  'nitrogen',
  'generated',
  'shared',
  'json'
);

/**
 * Every hand-written copy of a generated view config, keyed by the file name
 * nitrogen writes it to.
 */
const copies: Record<string, unknown> = {
  // @generated by scripts/gen-registry.mjs (region: config-copies) - do not edit; run bun run regen
  'NitroUiButtonConfig.json': NitroUiButtonConfig,
  'NitroUiDatePickerConfig.json': NitroUiDatePickerConfig,
  'NitroUiPickerConfig.json': NitroUiPickerConfig,
  'NitroUiProgressConfig.json': NitroUiProgressConfig,
  'NitroUiSegmentedControlConfig.json': NitroUiSegmentedControlConfig,
  'NitroUiSliderConfig.json': NitroUiSliderConfig,
  'NitroUiSwitchConfig.json': NitroUiSwitchConfig,
  'NitroUiMenuConfig.json': NitroUiMenuConfig,
  // @end-generated
  // `<Host>` again: no manifest, so no generated row.
  'NitroUiHostConfig.json': NitroUiHostConfig,
};

describe('hand-written view configs', () => {
  it('are all still generated by nitrogen', () => {
    expect(existsSync(generatedDir)).toBe(true);
  });

  it.each(Object.keys(copies))('%s matches nitrogen output', (fileName) => {
    const generated = JSON.parse(
      readFileSync(join(generatedDir, fileName), 'utf8')
    );
    expect(copies[fileName]).toEqual(generated);
  });

  it('covers every generated config (add the copy + an entry here)', () => {
    const generated = readdirSync(generatedDir).filter((file) =>
      file.endsWith('Config.json')
    );
    expect(Object.keys(copies).sort()).toEqual(generated.sort());
  });
});
